Two steps: create the Node, then attach the Component.

```cpp
auto* cache = GetSubsystem<ResourceCache>();
Node* mushroom = scene_->CreateChild("Mushroom");
mushroom->SetPosition(Vector3(0.0f, 0.0f, 3.0f));
auto* model = mushroom->CreateComponent<StaticModel>();
model->SetModel(cache->GetResource<Model>("Models/Mushroom.mdl"));
model->SetMaterial(cache->GetResource<Material>("Materials/Mushroom.xml"));
model->SetCastShadows(true);
```

Key rules:
- CreateChild() returns a Node*
- CreateComponent<T>() attaches a component TO that node and returns T*
- Never confuse the two — CreateChild does NOT return a component

Every scene needs an Octree component for rendering, and typically a Zone for ambient lighting:

```cpp
scene_ = new Scene(context_);
scene_->CreateComponent<Octree>();

// Zone for ambient light and fog
Node* zoneNode = scene_->CreateChild("Zone");
auto* zone = zoneNode->CreateComponent<Zone>();
zone->SetBoundingBox(BoundingBox(-1000.0f, 1000.0f));
zone->SetAmbientColor(Color(0.15f, 0.15f, 0.15f));
zone->SetFogColor(Color(0.5f, 0.5f, 0.7f));
zone->SetFogStart(100.0f);
zone->SetFogEnd(300.0f);
```

Scene is the root Node. Without Octree, nothing renders.

```cpp
Node* lightNode = scene_->CreateChild("DirectionalLight");
lightNode->SetDirection(Vector3(0.6f, -1.0f, 0.8f));
auto* light = lightNode->CreateComponent<Light>();
light->SetLightType(LIGHT_DIRECTIONAL);
light->SetCastShadows(true);
light->SetShadowBias(BiasParameters(0.00025f, 0.5f));
light->SetShadowCascade(CascadeParameters(10.0f, 50.0f, 200.0f, 0.0f, 0.8f));
```

Urho3D light type enums: LIGHT_DIRECTIONAL, LIGHT_POINT, LIGHT_SPOT. These are plain constants, NOT scoped enums (not LightType::Point).

```cpp
Node* lightNode = scene_->CreateChild("PointLight");
lightNode->SetPosition(Vector3(0.0f, 5.0f, 0.0f));
auto* light = lightNode->CreateComponent<Light>();
light->SetLightType(LIGHT_POINT);
light->SetColor(Color(1.0f, 0.8f, 0.6f));
light->SetRange(20.0f);
light->SetBrightness(1.5f);
```

The Node's position determines where the light is. The Component holds the light properties. This is the Node/Component pattern — position on Node, behavior on Component.

ResourceCache is the ONLY way to load assets. Never use fopen, std::ifstream, or POSIX calls.

```cpp
auto* cache = GetSubsystem<ResourceCache>();

// Models
auto* model = cache->GetResource<Model>("Models/Box.mdl");

// Materials
auto* mat = cache->GetResource<Material>("Materials/Stone.xml");

// Textures (use concrete type, not abstract Texture)
auto* tex = cache->GetResource<Texture2D>("Textures/Dirt.png");
auto* cube = cache->GetResource<TextureCube>("Textures/Sky.xml");

// Fonts
auto* font = cache->GetResource<Font>("Fonts/Anonymous Pro.ttf");

// XML files
auto* xml = cache->GetResource<XMLFile>("UI/DefaultStyle.xml");
```

Use Texture2D not Texture — Texture is the abstract base class.

Use SubscribeToEvent with the URHO3D_HANDLER macro:

```cpp
// Subscribe in Start() or constructor
SubscribeToEvent(E_UPDATE, URHO3D_HANDLER(MyClass, HandleUpdate));
SubscribeToEvent(E_KEYDOWN, URHO3D_HANDLER(MyClass, HandleKeyDown));

// Handler signature — always the same
void MyClass::HandleUpdate(StringHash eventType, VariantMap& eventData)
{
    using namespace Update;
    float timeStep = eventData[P_TIMESTEP].GetFloat();
}

void MyClass::HandleKeyDown(StringHash eventType, VariantMap& eventData)
{
    using namespace KeyDown;
    int key = eventData[P_KEY].GetInt();
    if (key == KEY_ESCAPE)
        engine_->Exit();
}
```

The 'using namespace' imports the event parameter constants (P_TIMESTEP, P_KEY, etc).

Use GetSubsystem<T>() — available on any Object-derived class:

```cpp
auto* cache = GetSubsystem<ResourceCache>();
auto* input = GetSubsystem<Input>();
auto* ui = GetSubsystem<UI>();
auto* graphics = GetSubsystem<Graphics>();
auto* renderer = GetSubsystem<Renderer>();
auto* audio = GetSubsystem<Audio>();
auto* network = GetSubsystem<Network>();
auto* fileSystem = GetSubsystem<FileSystem>();
auto* log = GetSubsystem<Log>();
```

These are singletons managed by Context. Never create them yourself — the Engine creates them at startup.

```cpp
// Create camera node
Node* cameraNode = scene_->CreateChild("Camera");
cameraNode->SetPosition(Vector3(0.0f, 5.0f, -10.0f));
auto* camera = cameraNode->CreateComponent<Camera>();
camera->SetFarClip(300.0f);

// Create viewport
auto* renderer = GetSubsystem<Renderer>();
SharedPtr<Viewport> viewport(new Viewport(context_, scene_, camera));
renderer->SetViewport(0, viewport);
```

The Viewport connects a Scene and Camera to a screen rectangle. Renderer::SetViewport(0, vp) sets the primary viewport. You can have multiple viewports for split-screen.

```cpp
auto* cache = GetSubsystem<ResourceCache>();
auto* ui = GetSubsystem<UI>();

Text* text = new Text(context_);
text->SetText("Hello World");
text->SetFont(cache->GetResource<Font>("Fonts/Anonymous Pro.ttf"), 15);
text->SetColor(Color(0.0f, 1.0f, 0.0f));
text->SetHorizontalAlignment(HA_CENTER);
text->SetVerticalAlignment(VA_CENTER);
ui->GetRoot()->AddChild(text);
```

UI elements are added to ui->GetRoot(). Alignment constants: HA_LEFT, HA_CENTER, HA_RIGHT, VA_TOP, VA_CENTER, VA_BOTTOM.

Add RigidBody and CollisionShape components to the same node:

```cpp
#include <Urho3D/Physics/RigidBody.h>
#include <Urho3D/Physics/CollisionShape.h>

Node* boxNode = scene_->CreateChild("Box");
boxNode->SetPosition(Vector3(0.0f, 10.0f, 0.0f));

// Visual
auto* model = boxNode->CreateComponent<StaticModel>();
model->SetModel(cache->GetResource<Model>("Models/Box.mdl"));

// Physics body
auto* body = boxNode->CreateComponent<RigidBody>();
body->SetMass(1.0f);  // 0 = static, >0 = dynamic
body->SetFriction(0.5f);

// Collision shape
auto* shape = boxNode->CreateComponent<CollisionShape>();
shape->SetBox(Vector3::ONE);  // unit box
```

Mass 0 = static (ground, walls). Mass > 0 = dynamic (moves with physics). Scene needs PhysicsWorld component: scene_->CreateComponent<PhysicsWorld>();

LogicComponent gives you Start, Update, and FixedUpdate callbacks:

```cpp
// MyComponent.h
#pragma once
#include <Urho3D/Scene/LogicComponent.h>

class MyComponent : public LogicComponent
{
    URHO3D_OBJECT(MyComponent, LogicComponent);
public:
    explicit MyComponent(Context* context);
    static void RegisterObject(Context* context);
    void Start() override;
    void Update(float timeStep) override;
private:
    float speed_;
};

// MyComponent.cpp
#include "MyComponent.h"

MyComponent::MyComponent(Context* context) : LogicComponent(context), speed_(5.0f)
{
    SetUpdateEventMask(USE_UPDATE);  // Enable Update callback
}

void MyComponent::RegisterObject(Context* context)
{
    context->RegisterFactory<MyComponent>();
    URHO3D_ATTRIBUTE("Speed", float, speed_, 5.0f, AM_DEFAULT);
}

void MyComponent::Start() { }

void MyComponent::Update(float timeStep)
{
    node_->Translate(Vector3::FORWARD * speed_ * timeStep);
}
```

Key points:
- URHO3D_OBJECT macro in class declaration (enables RTTI)
- RegisterObject is static, registers factory + serializable attributes
- SetUpdateEventMask(USE_UPDATE) enables the Update callback
- node_ gives access to the owning Node

```cpp
auto* cache = GetSubsystem<ResourceCache>();

Node* charNode = scene_->CreateChild("Character");
auto* animModel = charNode->CreateComponent<AnimatedModel>();
animModel->SetModel(cache->GetResource<Model>("Models/Animals/Fox.mdl"));
animModel->SetMaterial(cache->GetResource<Material>("Materials/Fox.xml"));
animModel->SetCastShadows(true);

// Add animation controller
auto* animCtrl = charNode->CreateComponent<AnimationController>();

// Play an animation
animCtrl->PlayExclusive("Models/Animals/Fox_AnimalArmatureIdle.ani", 0, true, 0.2f);
```

AnimatedModel replaces StaticModel for skeletal meshes. AnimationController manages playback:
- PlayExclusive(name, layer, looped, fadeTime) — play one anim, fade others out
- Play(name, layer, looped, fadeTime) — add to layer, blend with others
- Layer 0 is base body, higher layers can blend on top

SharedPtr is reference-counted ownership. Raw pointers are non-owning observers.

```cpp
// SharedPtr — you OWN this object, it lives as long as you hold it
SharedPtr<Scene> scene_(new Scene(context_));
SharedPtr<Viewport> viewport(new Viewport(context_, scene_, camera));

// Raw pointer — you're BORROWING, someone else owns it
auto* cache = GetSubsystem<ResourceCache>();  // Engine owns subsystems
Node* child = scene_->CreateChild("Foo");      // Scene owns nodes
auto* model = child->CreateComponent<StaticModel>(); // Node owns components

// WeakPtr — non-owning, but knows if the object was deleted
WeakPtr<Node> target(someNode);
if (!target.Expired())
    target->GetPosition();
```

Rule of thumb:
- Use SharedPtr for things you create with 'new' that aren't parented
- Use raw pointer (auto*) for things owned by scene/node/engine
- Use WeakPtr when you cache a reference that might get deleted

```cpp
auto* cache = GetSubsystem<ResourceCache>();
auto* ui = GetSubsystem<UI>();

// Load the default style
auto* style = cache->GetResource<XMLFile>("UI/DefaultStyle.xml");
ui->GetRoot()->SetDefaultStyle(style);

// Now UI elements auto-style when you call SetStyleAuto
Button* button = new Button(context_);
button->SetStyleAuto();
ui->GetRoot()->AddChild(button);

// Or apply a specific named style
LineEdit* edit = new LineEdit(context_);
edit->SetStyle("LineEdit");
ui->GetRoot()->AddChild(edit);
```

The default style must be loaded BEFORE creating any UI elements. This is a common mistake — if elements look invisible, check if the style was loaded first.

URHO3D_ATTRIBUTE registers a member variable for serialization and editor exposure:

```cpp
void MyComponent::RegisterObject(Context* context)
{
    context->RegisterFactory<MyComponent>();

    // URHO3D_ATTRIBUTE(name, type, variable, defaultValue, mode)
    URHO3D_ATTRIBUTE("Speed", float, speed_, 5.0f, AM_DEFAULT);
    URHO3D_ATTRIBUTE("Health", int, health_, 100, AM_DEFAULT);
    URHO3D_ATTRIBUTE("Name", String, name_, String::EMPTY, AM_DEFAULT);
    URHO3D_ATTRIBUTE("Active", bool, active_, true, AM_DEFAULT);

    // For properties with getters/setters:
    URHO3D_ACCESSOR_ATTRIBUTE("Color", GetColor, SetColor, Color, Color::WHITE, AM_DEFAULT);

    // For network-replicated attributes:
    URHO3D_ATTRIBUTE("Score", int, score_, 0, AM_DEFAULT | AM_NET);
}
```

AM_DEFAULT = saved to file + visible in editor. AM_NET = replicated over network. These attributes auto-serialize when saving/loading scenes.

Use VectorBuffer to pack data, Connection to send:

```cpp
// SENDING (client to server or server to client)
VectorBuffer buf;
buf.WriteString("hello");
buf.WriteFloat(42.0f);
buf.WriteVector3(position);
buf.WriteUInt(playerId);
connection->SendMessage(MSG_CHAT, true, true, buf);
// Args: msgID, reliable, inOrder, data

// RECEIVING (in HandleNetworkMessage)
void MyApp::HandleNetworkMessage(StringHash eventType, VariantMap& eventData)
{
    using namespace NetworkMessage;
    int msgID = eventData[P_MESSAGEID].GetInt();
    const auto& data = eventData[P_DATA].GetBuffer();
    MemoryBuffer msg(data);

    if (msgID == MSG_CHAT)
    {
        String text = msg.ReadString();
        float value = msg.ReadFloat();
        Vector3 pos = msg.ReadVector3();
        unsigned id = msg.ReadUInt();
    }
}
```

Read order MUST match write order. Protocol IDs go in Protocol.h.

Always use Urho3D's FileSystem and File classes — never raw fopen, std::ifstream, or POSIX calls:

```cpp
auto* fs = GetSubsystem<FileSystem>();

// Check if file exists
if (fs->FileExists("path/to/file.txt"))
    URHO3D_LOGINFO("File exists");

// Check/create directory
if (!fs->DirExists("mydir"))
    fs->CreateDir("mydir");

// Get special paths
String appDir = fs->GetProgramDir();
String prefDir = fs->GetAppPreferencesDir("urho3d", "myapp");

// Read a file
File file(context_, "path/to/file.txt", FILE_READ);
String content = file.ReadString();
file.Close();

// Write a file
File outFile(context_, "path/to/output.txt", FILE_WRITE);
outFile.WriteString("Hello\n");
outFile.Close();
```

Why: Urho3D's FileSystem handles platform differences (Android assets, iOS bundles, path separators). Raw POSIX breaks cross-platform.

Use Octree::RaycastSingle or Raycast for physics queries:

```cpp
// Graphics raycast (against rendered geometry)
auto* octree = scene_->GetComponent<Octree>();
Ray ray(origin, direction);  // origin = Vector3, direction = Vector3 (normalized)
PODVector<RayQueryResult> results;
RayOctreeQuery query(results, ray, RAY_TRIANGLE, 300.0f, DRAWABLE_GEOMETRY);
octree->Raycast(query);

if (results.Size() > 0)
{
    RayQueryResult& hit = results[0];
    Vector3 hitPos = hit.position_;
    Node* hitNode = hit.node_;
    float distance = hit.distance_;
}

// Physics raycast (against collision shapes)
auto* physics = scene_->GetComponent<PhysicsWorld>();
PhysicsRaycastResult result;
physics->RaycastSingle(result, ray, 300.0f);
if (result.body_)
{
    Vector3 hitPos = result.position_;
    Node* hitNode = result.body_->GetNode();
}
```

RAY_TRIANGLE = pixel-accurate. RAY_AABB = fast but rough. Use physics raycast when you need to hit collision shapes.

context_ is a pointer to the engine's Context — the central registry that holds all subsystems, object factories, and event routing.

```cpp
// Available as a member in any Object-derived class
class MyComponent : public LogicComponent
{
    // context_ is inherited from Object
    void DoStuff()
    {
        // Creating engine objects requires context_
        SharedPtr<Scene> scene(new Scene(context_));
        Text* text = new Text(context_);

        // GetSubsystem uses context_ internally
        auto* cache = GetSubsystem<ResourceCache>();
        // equivalent to: context_->GetSubsystem<ResourceCache>();
    }
};
```

Rules:
- Every Urho3D object constructor takes Context* as first argument
- context_ is always available in Object-derived classes
- Pass context_ when creating new objects with 'new'
- Never create your own Context — the Application creates the one and only

Use the Input subsystem — poll state or subscribe to events:

```cpp
auto* input = GetSubsystem<Input>();

// POLLING (in Update/HandleUpdate)
if (input->GetKeyDown(KEY_W))      // held down this frame
    MoveForward();
if (input->GetKeyPress(KEY_SPACE))  // just pressed (one frame)
    Jump();
if (input->GetMouseButtonDown(MOUSEB_LEFT))
    Shoot();

IntVector2 mouseMove = input->GetMouseMove();  // delta this frame
float wheel = input->GetMouseMoveWheel();

// EVENT-BASED (subscribe once)
SubscribeToEvent(E_KEYDOWN, URHO3D_HANDLER(MyApp, HandleKeyDown));

void MyApp::HandleKeyDown(StringHash eventType, VariantMap& eventData)
{
    using namespace KeyDown;
    int key = eventData[P_KEY].GetInt();
    if (key == KEY_F1)
        ToggleConsole();
}
```

KeyDown = pressed once, KeyUp = released, GetKeyDown = held. GetKeyPress = edge-triggered (true only on the frame it was pressed).

Attach a SoundSource3D component for positional audio, or SoundSource for ambient/UI:

```cpp
auto* cache = GetSubsystem<ResourceCache>();

// 3D positional sound (attenuates with distance)
Node* soundNode = scene_->CreateChild("SoundEffect");
soundNode->SetPosition(Vector3(10.0f, 0.0f, 5.0f));
auto* source = soundNode->CreateComponent<SoundSource3D>();
auto* sound = cache->GetResource<Sound>("Sounds/Hit.wav");
source->Play(sound);
source->SetNearDistance(1.0f);
source->SetFarDistance(50.0f);

// Ambient/UI sound (no position, constant volume)
auto* uiSource = scene_->CreateComponent<SoundSource>();
auto* music = cache->GetResource<Sound>("Music/Theme.ogg");
music->SetLooped(true);
uiSource->Play(music);
uiSource->SetGain(0.5f);
```

SoundListener component must be on the camera node for 3D audio to work: cameraNode->CreateComponent<SoundListener>();
Then set it: GetSubsystem<Audio>()->SetListener(listener);
